s=s.replace('Send the amount using Ravi’s bank details. Confirm after your bank shows it was sent.','Demo checkout only. No real card details or money are collected.').replace("sheet.querySelector('.bank-detail-link').hidden=method!=='bank'","sheet.querySelector('.bank-detail-link').hidden=true")
s=s.replace("const sheet=t.closest('.sheet');if(!noMotion())","const sheet=t.closest('.sheet');if(selectedMethod==='bank'){closeModal(t);modal(document.querySelector('#bill-pay'),'Card checkout · Demo',`<span class=\"pill amber\">SANDBOX / NO REAL CHARGE</span><h2>LKR 1,900.00</h2><p class=\"muted\">Live checkout requires payment gateway merchant setup. No card number or money is collected in this preview.</p><button class=\"primary\" onclick=\"closeModal(this)\">Back to bill</button>`);return}if(!noMotion())")
