s=s[:a]+'''function bankArt(){return `<svg viewBox="0 0 280 180" aria-hidden="true"><ellipse cx="140" cy="152" rx="94" ry="10" fill="#378ec4" opacity=".15"/><g transform="translate(40 30) rotate(-7 100 60)"><rect width="200" height="120" rx="20" fill="#235c87" stroke="#a6dfff"/><rect x="20" y="28" width="29" height="23" rx="5" fill="#b5d9e8"/><text x="20" y="80" font-size="15" fill="#d9f0ff" letter-spacing="3">••••  ••••  ••••</text><text x="20" y="103" font-size="10" fill="#a6dfff">DEMO CARD · NO CHARGE</text><circle cx="166" cy="95" r="12" fill="#88d4ff" opacity=".6"/></g></svg>`}'''+s[z:]
s=s.replace('Your provider confirms receipt after you report payment.','Cash: provider confirms receipt. Card: gateway verification required.').replace('Pay the provider directly. No money is collected by this screen.','Card is a demo. No real money is collected by this preview.')
