(dst/'board.html').write_text((src/'board.html').read_text(encoding='utf-8-sig').replace('BANK TRANSFER','CARD / DEMO').replace('Digital-wallet visual direction. No stored balance, no in-app money transfer.','Cash + card preview. Demo card checkout; no real charge.'),encoding='utf-8')
